#!/usr/bin/env python3
"""Keep the skill's tool table in step with the live Toolbelt MCP server.

Reads the tools the server actually exposes (anonymous account via /api/onboard,
then MCP initialize + tools/list) and rewrites the block between the markers in
toolbelt/SKILL.md and .github/known-tools.txt. When either changes, bumps the patch version of the npm
package, server.json and the skill, so publish-npm.yml ships it everywhere.

    sync_tools.py              # rewrite + bump when the server changed
    sync_tools.py --check      # exit 1 when SKILL.md is behind the server

Skips the account and the MCP calls when the server version recorded in the block
matches the live one, so an hourly schedule costs one GET.
Writes changed=true|false and version=<new package version> to $GITHUB_OUTPUT.
"""
import json
import os
import re
import sys
import urllib.request
from pathlib import Path

APP = "https://app.toolbelt.ai"
ROOT = Path(__file__).resolve().parents[2]
SKILL = ROOT / "toolbelt" / "SKILL.md"
PACKAGE = ROOT / "package.json"
SERVER_JSON = ROOT / "server.json"
KNOWN_TOOLS = ROOT / ".github" / "known-tools.txt"
KNOWN_HEADER = """# Registered MCP tools, as the live server lists them (tools/list on mcp.toolbelt.ai).
# Written by .github/scripts/sync_tools.py; CI fails if SKILL.md names a toolbelt_*
# tool that isn't here.
"""
BEGIN = "<!-- tools:begin"
END = "<!-- tools:end -->"
SYNCED = re.compile(r"Synced from the live server \(Toolbelt (\S+)\)")


def http(url, body=None, headers=None):
    req = urllib.request.Request(url, data=None if body is None else json.dumps(body).encode(),
                                 # Cloudflare refuses Python's default user agent.
                                 headers={"Content-Type": "application/json", "User-Agent": "toolbelt-skill-sync/1",
                                          **(headers or {})},
                                 method="GET" if body is None else "POST")
    with urllib.request.urlopen(req, timeout=60) as r:
        return r.read().decode(), r.headers


def rpc_result(text):
    """A streamable-HTTP reply is plain JSON or SSE `data:` lines."""
    for chunk in [text] + [l[5:].strip() for l in text.splitlines() if l.startswith("data:")]:
        try:
            msg = json.loads(chunk)
        except ValueError:
            continue
        if "error" in msg:
            raise SystemExit(f"MCP error: {msg['error']}")
        if "result" in msg:
            return msg["result"]
    raise SystemExit(f"no MCP result in reply: {text[:300]}")


def live_tools():
    onboard = json.loads(http(f"{APP}/api/onboard", {})[0])
    url = onboard["mcpUrl"]
    headers = {"Authorization": f"Bearer {onboard['token']}", "Accept": "application/json, text/event-stream"}
    text, h = http(url, {"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {
        "protocolVersion": "2025-06-18", "capabilities": {}, "clientInfo": {"name": "skill-sync", "version": "1"}}},
        headers)
    rpc_result(text)
    if h.get("mcp-session-id"):
        headers["Mcp-Session-Id"] = h["mcp-session-id"]
    http(url, {"jsonrpc": "2.0", "method": "notifications/initialized"}, headers)
    return rpc_result(http(url, {"jsonrpc": "2.0", "id": 2, "method": "tools/list"}, headers)[0])["tools"]


def summary(description):
    """The description's first sentence, on one line, safe in a table cell."""
    text = " ".join((description or "").split())
    m = re.match(r"(.+?[.!?])(\s|$)", text)
    text = m.group(1) if m else text
    if len(text) > 200:
        text = text[:197].rsplit(" ", 1)[0] + "..."
    return text.replace("|", "\\|")


def render(tools, server_version):
    rows = "\n".join(f"| `{t['name']}` | {summary(t.get('description'))} |" for t in tools)
    return (f"{BEGIN} (generated by .github/scripts/sync_tools.py; edit the server's tool descriptions, not this) -->\n"
            f"Synced from the live server (Toolbelt {server_version}): {len(tools)} tools.\n\n"
            f"| Tool | Purpose |\n|---|---|\n{rows}\n{END}")


def bump(version):
    major, minor, patch = (int(x) for x in version.split("."))
    return f"{major}.{minor}.{patch + 1}"


def output(**kv):
    if os.environ.get("GITHUB_OUTPUT"):
        with open(os.environ["GITHUB_OUTPUT"], "a") as f:
            f.writelines(f"{k}={v}\n" for k, v in kv.items())


def main():
    check = "--check" in sys.argv
    skill = SKILL.read_text()
    start, end = skill.find(BEGIN), skill.find(END)
    if start < 0 or end < 0:
        raise SystemExit(f"markers missing in {SKILL}")
    block = skill[start:end + len(END)]

    server_version = json.loads(http(f"{APP}/api/health/version")[0])["version"]
    recorded = SYNCED.search(block)
    if recorded and recorded.group(1) == server_version:
        print(f"up to date with Toolbelt {server_version}")
        output(changed="false")
        return

    tools = live_tools()
    known = KNOWN_HEADER + "".join(f"{n}\n" for n in sorted(t["name"] for t in tools))
    new_block = render(tools, server_version)
    if new_block == block and known == KNOWN_TOOLS.read_text():
        print("no change")
        output(changed="false")
        return
    if check:
        raise SystemExit(f"SKILL.md tool table is behind the live server (Toolbelt {server_version}); run sync_tools.py")

    KNOWN_TOOLS.write_text(known)
    skill = skill[:start] + new_block + skill[end + len(END):]
    skill = re.sub(r'^version: "(\d+\.\d+\.\d+)"', lambda m: f'version: "{bump(m.group(1))}"', skill, count=1,
                   flags=re.M)
    SKILL.write_text(skill)
    # Only the top-level "version" line changes, so the files keep their formatting.
    version = bump(json.loads(PACKAGE.read_text())["version"])
    for path in (PACKAGE, SERVER_JSON):
        path.write_text(re.sub(r'^(  "version": )"[^"]+"', rf'\g<1>"{version}"', path.read_text(), count=1,
                               flags=re.M))
    print(f"synced with Toolbelt {server_version}: package {version}")
    output(changed="true", version=version, server=server_version)


if __name__ == "__main__":
    main()
